def occurrence_range(values, target):
    def find_edge(bias_left):
        left, right = 0, len(values) - 1
        found = -1
        while left <= right:
            mid = left + (right - left) // 2
            if values[mid] == target:
                found = mid
                if bias_left:
                    right = mid - 1
                else:
                    left = mid + 1
            elif values[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return found

    return [find_edge(True), find_edge(False)]
